async function updateWeather(){const target=String(state.preferences.weatherLocation||'').trim();if(!target){state.weatherCache=null;renderWeather();return}try{const place=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(target)}&count=1&language=en&format=json`).then(r=>r.json()).then(x=>x.results?.[0]);if(!place)throw Error();const w=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}&current=temperature_2m,weather_code,is_day&daily=temperature_2m_max,temperature_2m_min,weather_code&temperature_unit=fahrenheit&timezone=auto`).then(r=>r.json());state.weatherCache={temperature:Math.round(w.current.temperature_2m),code:w.current.weather_code,location:place.name,forecast:(w.daily.time||[]).map((date,i)=>({date,high:Math.round(w.daily.temperature_2m_max[i]),low:Math.round(w.daily.temperature_2m_min[i]),code:w.daily.weather_code[i]})),updatedAt:Date.now()};save(false);renderWeather();}catch{renderWeather();}}
function renderWeather(){const w=state.weatherCache;if(!w)return;const icons=w.code>=95?'⛈️':w.code>=71?'❄️':w.code>=51?'🌧️':w.code>=2?'⛅':'☀️';document.querySelector('#weatherNow').textContent=`${w.temperature}°`;document.querySelector('#weatherIcon').textContent=icons;document.querySelector('#weatherAdvice').textContent=w.location;}
