function rememberDeletion(collection,id){state.syncTombstones=mergeSyncRecords(state.syncTombstones||[],[{id:`${collection}:${id}`,collection,recordId:id,deletedAt:new Date().toISOString()}]);}
function applyTombstones(){for(const tombstone of state.syncTombstones||[]){if(Array.isArray(state[tombstone.collection]))state[tombstone.collection]=state[tombstone.collection].filter(item=>item.id!==tombstone.recordId);}}
function connectSync(){clearTimeout(reconnectTimer);try{socket?.close()}catch{}socket=null;const c=state.syncSettings;if(!c.endpoint||!c.pairingCode){setSync('offline');return}if(!/^wss:\/\//i.test(c.endpoint)){setSync('error');return}setSync('connecting');try{socket=new WebSocket(c.endpoint);socket.onopen=async()=>{setSync('online');socket.send(JSON.stringify({type:'hello',roomId:await syncRoomId(),deviceId:c.deviceId,client:'daylight-mobile'}));setTimeout(sendSnapshot,600)};socket.onmessage=async e=>{try{const m=JSON.parse(e.data);if(m.type==='sync-request'){sendSnapshot();return}if(m.type!=='snapshot'||m.deviceId===c.deviceId||!m.encrypted)return;applySnapshot(await decryptSyncPayload(m.encrypted))}catch{setSync('error');toast('Desktop sync update failed')}};socket.onclose=()=>{setSync('offline');reconnectTimer=setTimeout(connectSync,2000)};socket.onerror=()=>setSync('error')}catch{setSync('error')}}
function applySnapshot(data){const changed=[];['customEvents','syncedCalendarEvents','todoItems','groceryItems','medications','people'].forEach(k=>{if(Array.isArray(data[k])){const merged=mergeSyncRecords(state[k]||[],data[k]);if(JSON.stringify(state[k])!==JSON.stringify(merged)){state[k]=merged;changed.push(k)}}});['bellSchedules','specialBellSchedules','routeSettings'].forEach(k=>{if(data[k]&&typeof data[k]==='object'&&JSON.stringify(state[k])!==JSON.stringify(data[k])){state[k]=data[k];changed.push(k)}});if(Array.isArray(data.scheduleOverrides)){const next=mergeSyncRecords((state.scheduleOverrides||[]).filter(x=>x.userException),data.scheduleOverrides);if(JSON.stringify(state.scheduleOverrides)!==JSON.stringify(next)){state.scheduleOverrides=next;changed.push('scheduleOverrides')}}if(data.preferences){const current=Object.fromEntries(Object.keys(data.preferences).map(k=>[k,state.preferences[k]]));if(JSON.stringify(current)!==JSON.stringify(data.preferences)){state.preferences={...state.preferences,...data.preferences};changed.push('preferences')}}save(false);if(!changed.length)return;renderHeader();const active=document.querySelector('.view.active')?.dataset.view;if(active==='today'&&changed.some(k=>['customEvents','syncedCalendarEvents','people','bellSchedules','specialBellSchedules','scheduleOverrides'].includes(k))){renderStudents();renderTodayEvents()}else if(active==='calendar'&&changed.some(k=>['customEvents','syncedCalendarEvents','people','scheduleOverrides'].includes(k)))renderCalendar();else if(active==='tasks'&&changed.some(k=>['todoItems','groceryItems','people'].includes(k)))renderTasks();else if(active==='agenda'&&changed.some(k=>['customEvents','syncedCalendarEvents','people','scheduleOverrides'].includes(k)))renderAgenda();document.querySelector('#noticeCount').hidden=!renderNotices().length;document.querySelector('#noticeCount').textContent=Math.min(9,renderNotices().length)}
const applySnapshotRecords=applySnapshot;
applySnapshot=function(data){if(Array.isArray(data.syncTombstones))state.syncTombstones=mergeSyncRecords(state.syncTombstones||[],data.syncTombstones);for(const tombstone of state.syncTombstones||[]){if(Array.isArray(data[tombstone.collection]))data[tombstone.collection]=data[tombstone.collection].filter(item=>item.id!==tombstone.recordId);}applyTombstones();const result=applySnapshotRecords(data);queueMicrotask(renderProfileImages);return result;};
async function sendSnapshot(){if(socket?.readyState!==WebSocket.OPEN)return;socket.send(JSON.stringify({type:'snapshot',roomId:await syncRoomId(),deviceId:state.syncSettings.deviceId,encrypted:await encryptSyncPayload(snapshot())}))}
async function refreshFamilyData(){const indicator=document.querySelector('#pullRefresh'),label=indicator?.querySelector('strong'),app=document.querySelector('#app');indicator?.classList.add('refreshing');if(label)label.textContent='Refreshing family…';try{if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'refresh-request',roomId:await syncRoomId(),deviceId:state.syncSettings.deviceId}));else connectSync();await updateWeather();renderAll();await new Promise(resolve=>setTimeout(resolve,650));if(label)label.textContent='Family updated';navigator.vibrate?.(16);await new Promise(resolve=>setTimeout(resolve,350))}catch{if(label)label.textContent='Could not refresh';await new Promise(resolve=>setTimeout(resolve,700))}finally{indicator?.classList.remove('refreshing');app?.classList.remove('refreshing-family');app?.style.removeProperty('--pull-progress');app?.style.setProperty('--pull-distance','0px');setTimeout(()=>app?.style.removeProperty('--pull-distance'),520);if(label)label.textContent='Pull to refresh'}}
function refreshMobileLiveMap(){const wrap=document.querySelector('#mobileLiveMapWrap');if(wrap)wrap.innerHTML=mobileRouteMapHtml()}
function stopLocationSharing(broadcast=true){if(locationWatchId!==null&&navigator.geolocation)navigator.geolocation.clearWatch(locationWatchId);locationWatchId=null;delete liveDeviceLocations[state.syncSettings.deviceId];if(broadcast)sendSnapshot();refreshMobileLiveMap()}
function startLocationSharing(){if(!state.mobilePreferences.locationSharing)return;if(!navigator.geolocation){state.mobilePreferences.locationSharing=false;save(false);toast('Location is not available on this device');return}if(locationWatchId!==null)return;locationWatchId=navigator.geolocation.watchPosition(position=>{const now=Date.now();liveDeviceLocations[state.syncSettings.deviceId]={lat:Number(position.coords.latitude),lng:Number(position.coords.longitude),accuracy:Math.round(position.coords.accuracy||0),updatedAt:now,name:state.profile.memberName||'Family phone',deviceId:state.syncSettings.deviceId};refreshMobileLiveMap();if(now-lastLocationSentAt>=5000){lastLocationSentAt=now;sendSnapshot()}},error=>{state.mobilePreferences.locationSharing=false;save(false);locationWatchId=null;const toggle=document.querySelector('#locationSharingToggle');if(toggle)toggle.checked=false;toast(error.code===1?'Location permission was not allowed':'Daylight could not update this phone’s location')},{enableHighAccuracy:true,maximumAge:4000,timeout:15000})}
function setSync(status){document.querySelector('#syncDot').className=status==='online'?'online':'';document.querySelector('#syncButton').dataset.status=status;}
function renderNotices(){const upcoming=allEvents().filter(e=>e.date>=iso(new Date())).sort((a,b)=>`${a.date}${a.time||''}`.localeCompare(`${b.date}${b.time||''}`)).slice(0,12),tasks=state.todoItems.filter(i=>!i.completed&&i.date<=iso(new Date())).map(i=>({title:i.title,detail:`To do · ${person(i.owner||'parents').name}`}));return[...tasks,...upcoming.map(e=>({title:e.title,detail:`${new Date(`${e.date}T12:00:00`).toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'})} · ${person(e.owner).name}`}))];}
function openSheet(type){const titles={quick:['CAPTURE','Quick add'],event:['QUICK ADD','Add an event'],task:['QUICK ADD','Add a task'],grocery:['QUICK ADD','Add groceries'],exception:['SCHOOL DAY','One-day exception'],notifications:['DAYLIGHT CENTER','Notifications'],notificationSettings:['SETTINGS','Notifications'],sync:['SETTINGS','Connections'],route:['MORNING DRIVE','School route'],health:['PRIVATE ON THIS DEVICE','Health & medication'],settings:['DAYLIGHT','Settings'],family:['SETTINGS','Family'],connections:['SETTINGS','Connections'],appearance:['SETTINGS','Appearance'],accessibility:['SETTINGS','Accessibility'],privacy:['SETTINGS','Privacy & data']},[eyebrow,title]=titles[type]||['DAYLIGHT','Details'];document.querySelector('#sheetEyebrow').textContent=eyebrow;document.querySelector('#sheetTitle').textContent=title;document.querySelector('#sheetBody').innerHTML=type==='settings'?settingsSheet():type==='accessibility'?accessibilitySheet():type==='privacy'?privacySheet():type==='family'?familySheet():sheetContent(type);if(type==='family')decorateFamilyProfilePhotos();document.querySelector('#sheetBackdrop').hidden=false;document.querySelector('#sheet').hidden=false;document.body.style.overflow='hidden';}
function familySheet(){return`<div class="family-member-list">${state.people.length?state.people.map(child=>`<article class="connection-card"><strong>${esc(child.name)}</strong><small>${esc(child.school||'School not added')}${child.grade?` · ${esc(child.grade)}`:''}</small><button type="button" data-remove-family-member="${child.id}">Remove</button></article>`).join(''):'<div class="empty">No children added yet.</div>'}</div><form id="familyMemberForm" class="sheet-form"><label>Child's name<input name="name" required placeholder="Full name"></label><label>School<input name="school" placeholder="School name"></label><label>Grade<input name="grade" placeholder="Grade"></label><label>Color<input name="color" type="color" value="#89a9ff"></label><button class="primary">Add child</button></form><div class="appearance-section"><span class="setting-label">IMPORTED BELL SCHEDULES</span>${(state.importedSchedules||[]).length?state.importedSchedules.map(item=>`<article class="connection-card"><strong>${esc(item.name)}</strong><small>${esc(displayName(person(item.ownerId)))} · Added ${new Date(item.createdAt).toLocaleDateString()}</small><button type="button" data-remove-imported-schedule="${item.id}">Delete</button></article>`).join(''):'<div class="empty">No screenshot schedules added.</div>'}</div>`;}
function decorateFamilyProfilePhotos(){document.querySelectorAll('.family-member-list .connection-card').forEach((card,index)=>{const child=state.people[index];if(!child)return;const removeChild=card.querySelector('[data-remove-family-member]');card.classList.add('family-member-card');card.insertAdjacentHTML('afterbegin',`<span class="family-profile-photo" style="--student:${child.color}">${avatarContent(child)}</span><div class="family-member-details"></div>`);const details=card.querySelector('.family-member-details');details.append(card.querySelector('strong'),card.querySelector('small'));card.insertAdjacentHTML('beforeend',`<label class="profile-photo-action">${profileImage(child)?'Change photo':'Add photo'}<input type="file" data-mobile-profile-photo="${child.id}" accept="image/png,image/jpeg,image/webp" hidden></label>${profileImage(child)?`<button type="button" data-remove-mobile-profile-photo="${child.id}">Remove photo</button>`:''}`);card.append(removeChild)})}
function mobileRouteMapHtml(){const routePoints=[state.routeSettings?.origin?.location,...(state.routeSettings?.stops||[]).map(stop=>stop.location)].filter(point=>Number.isFinite(point?.lat)&&Number.isFinite(point?.lng)),locations=Object.entries(liveDeviceLocations).filter(([,location])=>Date.now()-Number(location.updatedAt||0)<10*60*1000&&Number.isFinite(location.lat)&&Number.isFinite(location.lng));if(!routePoints.length&&!locations.length)return`<div class="mobile-map-empty">Live family locations will appear here after a connected phone shares its position.</div>`;const all=[...routePoints,...locations.map(([,location])=>location)],lats=all.map(point=>point.lat),lngs=all.map(point=>point.lng),minLat=Math.min(...lats)-.006,maxLat=Math.max(...lats)+.006,minLng=Math.min(...lngs)-.006,maxLng=Math.max(...lngs)+.006,dot=(location,label,type)=>{const left=((location.lng-minLng)/(maxLng-minLng))*100,top=(1-(location.lat-minLat)/(maxLat-minLat))*100;return`<span class="mobile-map-dot ${type}" style="left:${left}%;top:${top}%" title="${esc(label)}"><i></i></span>`};return`<div class="mobile-live-map"><iframe title="Live school route map" src="https://www.openstreetmap.org/export/embed.html?bbox=${minLng}%2C${minLat}%2C${maxLng}%2C${maxLat}&amp;layer=mapnik"></iframe>${routePoints.map((point,index)=>dot(point,index?'School':'Start','stop')).join('')}${locations.map(([,location])=>dot(location,location.name||'Family device','live')).join('')}</div><div class="mobile-location-list">${locations.length?locations.map(([,location])=>`<span><i></i><strong>${esc(location.name||'Family device')}</strong><small>Updated ${new Date(location.updatedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small></span>`).join(''):'<small>No phone is currently sharing a live location.</small>'}</div>`}
function locationSharingControl(){return`<label class="toggle-row live-location-toggle"><span><strong>Share this phone’s location</strong><small>Visible only to devices connected with your encrypted family code</small></span><input id="locationSharingToggle" type="checkbox" ${state.mobilePreferences.locationSharing?'checked':''}></label><div id="mobileLiveMapWrap">${mobileRouteMapHtml()}</div>`}
function closeSheet(){stopAssistantDictation();document.querySelector('#sheetBackdrop').hidden=true;document.querySelector('#sheet').hidden=true;document.body.style.overflow='';}
function sheetContent(type){if(type==='quick')return`<div class="quick-action-grid"><button data-sheet="event"><b>＋</b><strong>Event</strong><small>Calendar or appointment</small></button><button data-sheet="task"><b>✓</b><strong>To do</strong><small>Task with reminder</small></button><button data-sheet="grocery"><b>▣</b><strong>Groceries</strong><small>Add a household item</small></button><button data-sheet="health"><b>✚</b><strong>Health</strong><small>Medication or note</small></button><button data-sheet="exception"><b>⌁</b><strong>School change</strong><small>One-day exception</small></button><button id="quickVoice" type="button"><b>◉</b><strong>Speak</strong><small>Dictate an entry</small></button></div>`;if(type==='event')return`<form id="eventForm" class="sheet-form"><label>Title<input name="title" required placeholder="Appointment, practice, school event…"></label><label>For<select name="owner">${[...state.people,{id:'parents',name:'Parents'}].map(p=>`<option value="${p.id}">${esc(displayName(p))}</option>`).join('')}</select></label><label>Date<input name="date" type="date" value="${iso(selectedDate)}" required></label><label>Time<input name="time" type="time"></label><label>Reminder<select name="reminder"><option value="15">15 minutes before</option><option value="60">1 hour before</option><option value="120">2 hours before</option><option value="1440">1 day before</option><option value="0">No reminder</option></select></label><label class="toggle-row">Important<input name="priority" type="checkbox"></label><label class="toggle-row">Medical appointment<input name="medical" type="checkbox"></label><button class="primary">Add event</button></form>`;if(type==='task')return`<form id="quickTaskForm" class="sheet-form"><label>Task<input name="title" required placeholder="What needs to get done?"></label><label>For<select name="owner">${[...state.people,{id:'parents',name:'Parents'}].map(p=>`<option value="${p.id}">${esc(displayName(p))}</option>`).join('')}</select></label><label>Date<input name="date" type="date" value="${iso(selectedDate)}"></label><button class="primary">Add to list</button></form>`;if(type==='grocery')return`<form id="quickGroceryForm" class="sheet-form"><label>Grocery item<input name="title" required placeholder="Milk, fruit, sunscreen…"></label><label>Quantity<input name="quantity" placeholder="Optional"></label><button class="primary">Add groceries</button></form>`;if(type==='exception')return`<form id="exceptionForm" class="sheet-form"><label>Child<select name="owner">${state.people.map(p=>`<option value="${p.id}">${esc(displayName(p))}</option>`).join('')}</select></label><label>Date<input name="date" type="date" value="${iso(selectedDate)}" required></label><label>School begins<input name="arrival" type="time"></label><label>Pickup<input name="pickup" type="time"></label><label>Reason<input name="label" placeholder="Minimum day, late start…"></label><button class="primary">Apply for this day</button></form>`;if(type==='notifications'){const items=renderNotices();return`<button type="button" class="notification-settings-link" data-sheet="notificationSettings">Alert preferences</button>${items.length?items.map(i=>`<article class="notice-item"><strong>${esc(i.title)}</strong><small>${esc(i.detail)}</small></article>`).join(''):'<div class="empty">All caught up.</div>'}`;}if(type==='notificationSettings'){const p=state.mobilePreferences;return`<form id="notificationForm" class="sheet-form"><label class="toggle-row"><span><strong>Mobile notifications</strong><small>Enable Daylight alerts on this device</small></span><input name="notifications" type="checkbox" ${p.notifications?'checked':''}></label><label class="toggle-row">Departure alerts<input name="departureAlerts" type="checkbox" ${p.departureAlerts?'checked':''}></label><label class="toggle-row">Pickup alerts<input name="pickupAlerts" type="checkbox" ${p.pickupAlerts?'checked':''}></label><label class="toggle-row">Event and appointment alerts<input name="eventAlerts" type="checkbox" ${p.eventAlerts?'checked':''}></label><div class="two-field"><label>Quiet hours begin<input name="quietStart" type="time" value="${p.quietStart||'21:00'}"></label><label>Quiet hours end<input name="quietEnd" type="time" value="${p.quietEnd||'06:00'}"></label></div><button class="primary">Save alert preferences</button></form>`;}if(type==='sync'||type==='connections')return`<div class="connection-card"><strong>Desktop sync · ${socket?.readyState===WebSocket.OPEN?'Connected':'Offline ready'}</strong><small>Changes stay on this phone until a secure relay is available.</small></div><form id="syncForm" class="sheet-form"><label>Secure relay address<input name="endpoint" value="${esc(state.syncSettings.endpoint)}" placeholder="wss://your-daylight-relay.example"></label><label>Pairing code<input name="pairingCode" value="${esc(state.syncSettings.pairingCode)}" placeholder="Same code as desktop"></label><label>This device<input value="${esc(state.syncSettings.deviceId)}" disabled></label><button class="primary">Save and connect</button></form><div class="connection-card"><strong>Weather</strong><small>${state.weatherCache?'Connected through Open-Meteo':'Waiting for network'}</small></div><div class="connection-card"><strong>Offline storage</strong><small>Active · schedules and lists remain available without a connection.</small></div>`;if(type==='route')return`${locationSharingControl()}<label class="toggle-row"><span><strong>Show next drop-off</strong><small>Optional guidance for families who want the next stop called out</small></span><input id="nextDropoffToggle" type="checkbox" ${state.mobilePreferences.showNextDropoff?'checked':''}></label><div class="connection-card route-intro"><strong>Morning order</strong><small>All stops remain visible whether guidance is on or off.</small></div><div class="route-stop-list">${(state.routeSettings.stops||[]).map((s,i)=>routeStopHtml(s,i)).join('')}</div><button class="primary" id="openRoute">Open full route</button>`;if(type==='health')return`<form id="medForm" class="sheet-form"><label>Medication or health note<input name="title" required></label><label>For<select name="owner">${state.people.map(p=>`<option value="${p.id}">${esc(displayName(p))}</option>`).join('')}</select></label><label>Instructions<textarea name="instructions"></textarea></label><button class="primary">Save health item</button></form>${(state.medications||[]).map(m=>`<div class="connection-card"><strong>${esc(m.title)}</strong><small>${esc(displayName(person(m.owner)))} · ${esc(m.instructions||'No instructions')}</small></div>`).join('')}`;if(type==='appearance')return appearanceSheet();return'';}
function routeStopHtml(stop,index){const raw=stop.formattedAddress||stop.address||'',parts=raw.split(',').map(part=>part.trim()).filter(Boolean),street=parts[0]||'Address not verified',locality=parts.slice(1,3).join(', '),ownerId=stop.personId||stop.id;return`<article class="route-stop"><b>${index+1}</b><div><strong>${esc(displayName(person(ownerId)))}</strong><span>${esc(stop.school||person(ownerId)?.school||'School')}</span><small><em>${esc(street)}</em>${locality?`<i>${esc(locality)}</i>`:''}</small></div></article>`;}
function appearanceSheet(){const p=state.mobilePreferences;return`<form id="appearanceForm" class="appearance-form"><div class="appearance-section"><span class="setting-label">DISPLAY NAMES · THIS DEVICE ONLY</span>${state.people.map(child=>`<label>${esc(child.name)}<input name="alias-${child.id}" value="${esc(p.aliases?.[child.id]||'')}" placeholder="Display as ${esc(child.name.split(' ')[0])}"></label>`).join('')}</div><div class="appearance-section"><span class="setting-label">THEME</span><label class="toggle-row">Light mode<input id="themeToggle" type="checkbox" ${p.theme==='light'?'checked':''}></label><label>Liquid glass<select id="glassMode"><option value="clear" ${p.glassMode==='clear'?'selected':''}>Clear and airy</option><option value="balanced" ${p.glassMode==='balanced'?'selected':''}>Balanced</option><option value="frosted" ${p.glassMode==='frosted'?'selected':''}>Frosted</option><option value="solid" ${p.glassMode==='solid'?'selected':''}>High readability</option></select></label><label>Background<select id="mobileBackground"><option value="aurora" ${p.background==='aurora'?'selected':''}>Aurora night</option><option value="ocean" ${p.background==='ocean'?'selected':''}>Ocean blue</option><option value="berry" ${p.background==='berry'?'selected':''}>Berry dusk</option><option value="graphite" ${p.background==='graphite'?'selected':''}>Graphite</option></select></label><div class="accent-row">${['#89a9ff','#62d2b3','#ff77bd','#a98cff','#f0b85b'].map(color=>`<button type="button" data-mobile-accent="${color}" class="${p.accent===color?'active':''}" style="--swatch:${color}" aria-label="Use ${color}"></button>`).join('')}</div></div><div class="appearance-section"><span class="setting-label">TODAY EXPERIENCE</span><label class="toggle-row"><span><strong>Live countdowns</strong><small>Show time remaining in the current block</small></span><input id="countdownsToggle" type="checkbox" ${p.showCountdowns?'checked':''}></label><label class="toggle-row"><span><strong>Compact finished days</strong><small>Reduce completed school cards</small></span><input id="compactFinishedToggle" type="checkbox" ${p.compactFinished?'checked':''}></label><label class="toggle-row"><span><strong>Show next drop-off</strong><small>Optional route guidance; off by default</small></span><input id="appearanceDropoffToggle" type="checkbox" ${p.showNextDropoff?'checked':''}></label></div><div class="appearance-section"><span class="setting-label">ACCESSIBILITY</span><label class="toggle-row">Larger text<input id="largeTextToggle" type="checkbox" ${p.largeText?'checked':''}></label><label class="toggle-row">Larger touch targets<input id="largeTargetsToggle" type="checkbox" ${p.largeTargets?'checked':''}></label><label class="toggle-row">High contrast<input id="highContrastToggle" type="checkbox" ${p.highContrast?'checked':''}></label><label class="toggle-row">Reduce motion<input id="motionToggle" type="checkbox" ${p.reduceMotion?'checked':''}></label></div><button class="primary">Save on this phone</button><small class="local-note">These choices stay on this device and never rename a child in the shared family system.</small></form>`;}
function navigate(name,fromGesture=false){
  if(fromGesture)document.documentElement.classList.add('gesture-navigation');
  document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));
  document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));
  window.scrollTo({top:0,behavior:fromGesture||state.mobilePreferences.reduceMotion?'auto':'smooth'});
  if(fromGesture)requestAnimationFrame(()=>document.documentElement.classList.remove('gesture-navigation'));
}
function toast(message){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=message;t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,2500)}
function applyMobileAppearance(){const p=state.mobilePreferences||{};document.body.classList.toggle('light',p.theme==='light');document.body.classList.toggle('mobile-large-text',Boolean(p.largeText));document.body.classList.toggle('mobile-large-targets',Boolean(p.largeTargets));document.body.classList.toggle('mobile-high-contrast',Boolean(p.highContrast));document.body.classList.toggle('mobile-reduce-motion',Boolean(p.reduceMotion));document.body.dataset.glass=p.glassMode||'balanced';document.body.dataset.background=p.background||'aurora';document.documentElement.style.setProperty('--accent',p.accent||'#89a9ff');const statusColors=p.theme==='light'?{aurora:'#dce8f5',ocean:'#d7edf4',berry:'#eee0ec',graphite:'#e1e7ea'}:{aurora:'#08111b',ocean:'#071925',berry:'#180f21',graphite:'#0b1014'},statusColor=statusColors[p.background]||statusColors.aurora;document.documentElement.style.backgroundColor=statusColor;document.body.style.backgroundColor=statusColor;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',statusColor);}
