function assistant(prompt){const text=String(prompt||'').trim(),reply=document.querySelector('#assistantReply');const add=text.match(/add (.+?)(?: on | )(today|tomorrow|\d{4}-\d{2}-\d{2})(?: at (\d{1,2}(?::\d{2})?\s?(?:am|pm)?))?/i);if(add){const date=new Date();if(add[2].toLowerCase()==='tomorrow')date.setDate(date.getDate()+1);else if(/^\d/.test(add[2]))date.setTime(new Date(`${add[2]}T12:00:00`).getTime());const selectedPerson=state.people.find(person=>text.toLowerCase().includes(person.name.toLowerCase())||text.toLowerCase().includes(person.name.split(' ')[0].toLowerCase())),title=add[1].replace(new RegExp(`\\s+for\\s+${selectedPerson?.name.split(' ')[0]||'parents'}$`,'i'),'');state.customEvents.push({id:uid(),title,owner:selectedPerson?.id||'parents',date:iso(date),time:'',source:'Daylight Assistant'});save();renderAll();reply.textContent=`Added “${title}” to ${iso(date)}.`;return}if(/schedule/i.test(text)){reply.textContent=state.people.map(p=>{const s=daySchedule(p.id,selectedDate);return`${p.name.split(' ')[0]}: ${s.name}, ${s.rows.length} blocks.`}).join(' ');return}reply.textContent=`Today has ${calendarEvents(selectedDate).length} calendar events and ${state.todoItems.filter(i=>i.date===iso(selectedDate)&&!i.completed).length} open tasks. I can also add an event or show the school schedule.`;}
