function shrinkScheduleImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const image=new Image();image.onerror=reject;image.onload=()=>{const scale=Math.min(1,1800/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.86))};image.src=reader.result};reader.readAsDataURL(file)})}
function scheduleImportSummary(result){return result.schedules.map(schedule=>`<article><strong>${esc(schedule.name)}</strong><small>${schedule.weekdays.length?`Repeats: ${schedule.weekdays.map(day=>['','Mon','Tue','Wed','Thu','Fri'][day]).join(', ')}`:''}${schedule.dates.length?`${schedule.weekdays.length?' · ':''}${schedule.dates.length} dated day${schedule.dates.length===1?'':'s'}`:''}</small>${schedule.rows.map(row=>`<div><span>${esc(row.title)}</span><b>${esc(fmtTime(row.start))}–${esc(fmtTime(row.end))}</b></div>`).join('')}</article>`).join('')}
async function parseScheduleScreenshots(files){
  if(!state.people.length){toast('Add a child before importing a schedule');return}
  const accepted=[...files].filter(file=>/^image\/(png|jpeg|webp)$/i.test(file.type));if(!accepted.length)return;
  const button=document.querySelector('#attachScheduleImages'),result=document.querySelector('#scheduleImportResult'),list=document.querySelector('#scheduleImageList');button.disabled=true;button.querySelector('small').textContent='Reading schedule…';pendingScheduleImport=null;result.hidden=true;
  try{scheduleImportImages=await Promise.all(accepted.map(shrinkScheduleImage));list.hidden=false;list.innerHTML=scheduleImportImages.map((src,index)=>`<img src="${src}" alt="Schedule screenshot ${index+1}">`).join('');const owner=person(document.querySelector('#scheduleImportOwner').value),combined={studentName:owner.name,school:owner.school||'',notes:'',schedules:[]};for(let index=0;index<scheduleImportImages.length;index+=5){button.querySelector('small').textContent=`Reading ${index+1}–${Math.min(index+5,scheduleImportImages.length)} of ${scheduleImportImages.length}`;const response=await fetch(scheduleRelayUrl(),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({roomId:await syncRoomId(),studentName:owner.name,school:owner.school||'',images:scheduleImportImages.slice(index,index+5)})});const data=await response.json();if(!response.ok)throw Error(data.error||'Schedule import failed');combined.schedules.push(...(data.schedule.schedules||[]));if(data.schedule.notes)combined.notes+=(combined.notes?' ':'')+data.schedule.notes}pendingScheduleImport=combined;result.hidden=false;result.innerHTML=`<div class="import-review"><small>REVIEW BEFORE ADDING</small><h3>${esc(combined.studentName||owner.name)} · ${combined.schedules.length} schedule${combined.schedules.length===1?'':'s'}</h3>${combined.notes?`<p>${esc(combined.notes)}</p>`:''}${scheduleImportSummary(combined)}<div class="import-actions"><button type="button" data-cancel-schedule-import>Cancel</button><button type="button" class="primary" data-apply-schedule-import>Add to Daylight</button></div></div>`}catch(error){result.hidden=false;result.innerHTML=`<p class="import-error">${esc(error.message||'Schedule import failed.')}</p>`}finally{button.disabled=false;button.querySelector('small').textContent='Choose screenshots or photos for Daylight to read'}
}
function applyImportedSchedule(){const ownerId=document.querySelector('#scheduleImportOwner').value;if(!pendingScheduleImport||!ownerId)return;state.bellSchedules[ownerId]||={};state.specialBellSchedules[ownerId]||={};state.importedSchedules||=[];for(const schedule of pendingScheduleImport.schedules){const rows=schedule.rows.map(row=>[row.title,row.start,row.end]);for(const weekday of schedule.weekdays)state.bellSchedules[ownerId][weekday]=rows;for(const date of schedule.dates)state.specialBellSchedules[ownerId][date]={name:schedule.name,rows};state.importedSchedules.push({id:uid(),ownerId,name:schedule.name,weekdays:[...schedule.weekdays],dates:[...schedule.dates],rows,createdAt:new Date().toISOString()})}save();pendingScheduleImport=null;scheduleImportImages=[];document.querySelector('#scheduleImageList').hidden=true;document.querySelector('#scheduleImportResult').hidden=true;document.querySelector('#scheduleImageFiles').value='';renderAll();toast('Bell schedule added')}
