const openStandardSheet=openSheet;
openSheet=function(type){if(type!=='assistant')return openStandardSheet(type);document.querySelector('#sheetEyebrow').textContent='ASK DAYLIGHT';document.querySelector('#sheetTitle').textContent='Your family assistant';document.querySelector('#sheetBody').innerHTML=`<div class="assistant-popup"><form id="assistantForm" class="assistant-form"><label>What can Daylight help with?<textarea name="prompt" required placeholder="Add an appointment, summarize today, or ask about a schedule…"></textarea></label><div class="assistant-controls"><button type="button" id="assistantVoice" class="dictate-button">◉ Dictate</button><button class="primary">Ask Daylight</button></div></form><div id="assistantReply" class="assistant-reply">I can add events and list items, find schedules, summarize the day, and help organize your family.</div></div>`;document.querySelector('#sheetBackdrop').hidden=false;document.querySelector('#sheet').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('#assistantForm textarea')?.focus(),80)};
let assistantRecognition=null,assistantRecognitionTimer=null;
function resetAssistantDictationButton(message='◉ Dictate'){
  const button=document.querySelector('#assistantVoice');
  if(button){button.disabled=false;button.classList.remove('listening');button.textContent=message}
}
function stopAssistantDictation(){
  clearTimeout(assistantRecognitionTimer);assistantRecognitionTimer=null;
  if(assistantRecognition){try{assistantRecognition.abort()}catch{}assistantRecognition=null}
  resetAssistantDictationButton();
}
document.addEventListener('click',event=>{
  const button=event.target.closest('#assistantVoice');if(!button)return;
  if(assistantRecognition){stopAssistantDictation();toast('Dictation stopped');return}
  const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!Recognition){toast('Dictation is not supported by this browser');return}
  const recognition=new Recognition();assistantRecognition=recognition;
  recognition.lang=navigator.language||'en-US';recognition.interimResults=false;recognition.continuous=false;recognition.maxAlternatives=1;
  let transcriptReceived=false,started=false;
  const finish=(message='◉ Dictate')=>{
    clearTimeout(assistantRecognitionTimer);assistantRecognitionTimer=null;
    if(assistantRecognition===recognition)assistantRecognition=null;
    resetAssistantDictationButton(message);
  };
  button.disabled=false;button.classList.add('listening');button.textContent='Starting…';
  recognition.onstart=()=>{started=true;button.textContent='Listening…';assistantRecognitionTimer=setTimeout(()=>{try{recognition.stop()}catch{}finish();toast('No speech heard. Tap Dictate to try again')},12000)};
  recognition.onspeechend=()=>{try{recognition.stop()}catch{}};
  recognition.onresult=result=>{
    const transcript=Array.from(result.results).map(item=>item[0]?.transcript||'').join(' ').trim();
    if(!transcript)return;
    transcriptReceived=true;const field=document.querySelector('#assistantForm textarea');
    if(field){field.value=transcript;field.dispatchEvent(new Event('input',{bubbles:true}));field.focus()}
    finish();navigator.vibrate?.(12);toast('Dictation added');
  };
  recognition.onnomatch=()=>{finish();toast('I could not understand that. Please try again')};
  recognition.onerror=error=>{
    const reason=error.error;finish();
    if(reason==='aborted')return;
    if(reason==='not-allowed'||reason==='service-not-allowed')toast('Microphone access is required for dictation');
    else if(reason==='no-speech')toast('No speech heard. Tap Dictate to try again');
    else if(reason==='network')toast('Dictation needs an internet connection in Safari');
    else toast('Dictation stopped. Please try again');
  };
  recognition.onend=()=>{
    if(assistantRecognition!==recognition)return;
    finish();
    if(started&&!transcriptReceived)toast('No speech captured. Tap Dictate to try again');
  };
  assistantRecognitionTimer=setTimeout(()=>{if(!started){try{recognition.abort()}catch{}finish();toast('Dictation could not start. Please try again')}},5000);
  try{recognition.start()}catch{finish();toast('Dictation could not start. Please try again')}
});
let studentDrag=null,studentHold=null,studentReady=null,studentStart=null,suppressStudentClick=false;
document.addEventListener('pointerdown',event=>{const header=event.target.closest('.student-head'),card=header?.closest('.student-card');if(!card||event.target.closest('button'))return;event.preventDefault();studentStart={x:event.clientX,y:event.clientY,id:event.pointerId,card};studentReady=setTimeout(()=>card.classList.add('hold-ready'),120);studentHold=setTimeout(()=>{studentDrag=card;suppressStudentClick=true;card.classList.remove('hold-ready');card.classList.add('dragging');navigator.vibrate?.([18,25,18]);header.setPointerCapture?.(event.pointerId)},300)});
document.addEventListener('pointermove',event=>{if(!studentDrag){if(studentStart&&studentStart.id===event.pointerId&&Math.hypot(event.clientX-studentStart.x,event.clientY-studentStart.y)>9){clearTimeout(studentHold);clearTimeout(studentReady);studentStart.card?.classList.remove('hold-ready');studentHold=null;studentReady=null;studentStart=null}return}event.preventDefault();const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('.student-card');if(target&&target!==studentDrag&&target.parentElement===studentDrag.parentElement){const box=target.getBoundingClientRect();target.parentElement.insertBefore(studentDrag,event.clientY<box.top+box.height/2?target:target.nextSibling)}},{passive:false});
function finishStudentDrag(){clearTimeout(studentHold);clearTimeout(studentReady);studentHold=null;studentReady=null;studentStart?.card?.classList.remove('hold-ready');studentStart=null;if(!studentDrag)return;studentDrag.classList.remove('dragging');const order=[...document.querySelectorAll('#studentCards .student-card')].map(card=>card.dataset.student),byId=new Map(state.people.map(child=>[child.id,child]));state.people=order.map(id=>byId.get(id)).filter(Boolean);studentDrag=null;save();toast('Student order saved');setTimeout(()=>suppressStudentClick=false,140)}
document.addEventListener('pointerup',finishStudentDrag);document.addEventListener('pointercancel',finishStudentDrag);document.addEventListener('click',event=>{if(suppressStudentClick&&event.target.closest('.student-card')){event.preventDefault();event.stopImmediatePropagation()}},true);
document.addEventListener('contextmenu',event=>{if(event.target.closest('.student-card'))event.preventDefault()});

function settingsSheet(){return`<div class="settings-hub"><button type="button" data-sheet="family"><span>F</span><div><strong>Family</strong><small>Children, schools, profile photos, and local display names</small></div><i>›</i></button><button type="button" data-sheet="appearance"><span>◐</span><div><strong>Appearance</strong><small>Theme, colors, backgrounds, and Today layout</small></div><i>›</i></button><button type="button" data-sheet="accessibility"><span>Aa</span><div><strong>Accessibility</strong><small>Text size, touch targets, contrast, and motion</small></div><i>›</i></button><button type="button" data-sheet="notificationSettings"><span>♢</span><div><strong>Notifications</strong><small>Departure, pickup, event alerts, and quiet hours</small></div><i>›</i></button><button type="button" data-sheet="connections"><span>⌁</span><div><strong>Connections</strong><small>Desktop sync, relay, weather, and offline status</small></div><i>›</i></button><button type="button" data-sheet="privacy"><span>◇</span><div><strong>Privacy & data</strong><small>Location sharing and what stays on this device</small></div><i>›</i></button></div>`}
function accessibilitySheet(){const p=state.mobilePreferences;return`<form id="accessibilityForm" class="appearance-form"><div class="appearance-section"><span class="setting-label">READABILITY</span><label class="toggle-row"><span><strong>Larger text</strong><small>Increase text throughout Daylight</small></span><input name="largeText" type="checkbox" ${p.largeText?'checked':''}></label><label class="toggle-row"><span><strong>Larger touch targets</strong><small>Make controls easier to press</small></span><input name="largeTargets" type="checkbox" ${p.largeTargets?'checked':''}></label><label class="toggle-row"><span><strong>High contrast</strong><small>Strengthen text, icons, and borders</small></span><input name="highContrast" type="checkbox" ${p.highContrast?'checked':''}></label></div><div class="appearance-section"><span class="setting-label">MOTION</span><label class="toggle-row"><span><strong>Reduce motion</strong><small>Minimize page, popup, and interface animation</small></span><input name="reduceMotion" type="checkbox" ${p.reduceMotion?'checked':''}></label></div><button class="primary">Save accessibility</button></form>`}
function privacySheet(){return`<div class="privacy-settings"><article class="connection-card"><strong>Family information</strong><small>Your schedules, lists, aliases, and preferences remain on this device and sync only through your family’s secure pairing code.</small></article>${locationSharingControl()}<article class="connection-card"><strong>Offline storage</strong><small>Active. Daylight remains useful without a network connection.</small></article><article class="connection-card"><strong>Local display choices</strong><small>Appearance and accessibility preferences stay on this phone and do not alter another family member’s device.</small></article></div>`}
document.addEventListener('click',event=>{const target=event.target.closest('[data-sheet]');if(!target)return;requestAnimationFrame(()=>{if(target.dataset.sheet==='appearance')document.querySelectorAll('#sheetBody .appearance-section').forEach(section=>{const label=section.querySelector('.setting-label')?.textContent||'';if(label.includes('DISPLAY NAMES')||label.includes('ACCESSIBILITY'))section.hidden=true});if(target.dataset.sheet==='family'&&!document.querySelector('#deviceNamesForm')){const form=document.createElement('form');form.id='deviceNamesForm';form.className='appearance-section sheet-form';form.innerHTML=`<span class="setting-label">DISPLAY NAMES · THIS PHONE ONLY</span>${state.people.map(child=>`<label>${esc(child.name)}<input name="alias-${child.id}" value="${esc(state.mobilePreferences.aliases?.[child.id]||'')}" placeholder="Display as ${esc(child.name.split(' ')[0])}"></label>`).join('')}<button class="primary">Save display names</button>`;document.querySelector('#sheetBody').prepend(form)}})},true);
document.addEventListener('submit',event=>{if(event.target.id==='accessibilityForm'){event.preventDefault();event.stopImmediatePropagation();const data=new FormData(event.target);state.mobilePreferences.largeText=data.get('largeText')==='on';state.mobilePreferences.largeTargets=data.get('largeTargets')==='on';state.mobilePreferences.highContrast=data.get('highContrast')==='on';state.mobilePreferences.reduceMotion=data.get('reduceMotion')==='on';save(false);applyMobileAppearance();closeSheet();toast('Accessibility saved');return}if(event.target.id==='deviceNamesForm'){event.preventDefault();event.stopImmediatePropagation();const data=new FormData(event.target);state.people.forEach(child=>state.mobilePreferences.aliases[child.id]=String(data.get(`alias-${child.id}`)||'').trim());save(false);closeSheet();renderAll();toast('Display names saved on this phone')}},true);

/* Native-feeling navigation gestures. Horizontal page swipes deliberately
   ignore controls and horizontal scrollers; sheets dismiss only on a clear
   downward gesture while their content is already at the top. */
const mobilePageOrder=['today','calendar','agenda','tasks','more'];
const DAYLIGHT_BUILD_COMMIT='__DAYLIGHT_COMMIT__';
const DAYLIGHT_COMMIT_API='https://api.github.com/repos/SvenskaXCVI/Daylight/commits/main';
const shortCommit=value=>value&&value!=='__DAYLIGHT_COMMIT__'?String(value).slice(0,7):'Local';
async function newestGithubCommit(){const response=await fetch(DAYLIGHT_COMMIT_API,{cache:'no-store',headers:{Accept:'application/vnd.github+json'}});if(!response.ok)throw new Error('GitHub unavailable');return String((await response.json()).sha||'')}
async function renderGithubUpdate(){const installed=document.querySelector('#installedCommit'),latest=document.querySelector('#latestCommit'),status=document.querySelector('#githubUpdateStatus');if(!installed||!latest||!status)return;installed.textContent=shortCommit(DAYLIGHT_BUILD_COMMIT);try{const commit=await newestGithubCommit();latest.textContent=shortCommit(commit);status.textContent=DAYLIGHT_BUILD_COMMIT===commit?'Daylight is on the newest version.':'A newer Daylight build is ready.'}catch{latest.textContent='Offline';status.textContent='Connect to the internet to check for updates.'}}
async function updateFromGithub(){const button=document.querySelector('#githubUpdateButton');if(!button||button.disabled)return;button.disabled=true;button.textContent='Checking GitHub…';try{const newest=await newestGithubCommit();document.querySelector('#latestCommit').textContent=shortCommit(newest);if(DAYLIGHT_BUILD_COMMIT===newest){document.querySelector('#githubUpdateStatus').textContent='Daylight is on the newest version.';toast('Daylight is already up to date');return}button.textContent='Installing update…';document.querySelector('#githubUpdateStatus').textContent='Downloading the newest Daylight build…';const registration=await navigator.serviceWorker?.getRegistration(),previousController=navigator.serviceWorker?.controller;if(!registration||!previousController)throw new Error('Updater is not ready');const controllerChanged=new Promise(resolve=>navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true}));await registration.update();if(registration.installing||registration.waiting)await Promise.race([controllerChanged,new Promise(resolve=>setTimeout(resolve,10000))]);const controller=navigator.serviceWorker.controller;if(!controller)throw new Error('Updater is not ready');await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Update timed out')),20000);const receive=event=>{if(event.data?.type!=='DAYLIGHT_UPDATE_READY')return;clearTimeout(timer);navigator.serviceWorker.removeEventListener('message',receive);resolve()};navigator.serviceWorker.addEventListener('message',receive);controller.postMessage({type:'REFRESH_DAYLIGHT_APP'})});button.textContent='Restarting Daylight…';location.reload()}catch(error){document.querySelector('#githubUpdateStatus').textContent='The update could not be completed. Your current version is unchanged.';toast(error.message==='GitHub unavailable'?'GitHub could not be reached':'Update failed — try again')}finally{button.disabled=false;if(button.textContent!=='Restarting Daylight…')button.textContent='Update from GitHub'}}
document.querySelector('#githubUpdateButton')?.addEventListener('click',updateFromGithub);
renderGithubUpdate();
let pageGesture=null,sheetGesture=null,suppressPageTap=false;
const gestureControl=target=>target.closest('.unified-header,.bottom-nav,.sheet,.sheet-backdrop,.floating-actions,.student-head,.student-card.dragging,#onboarding');
const gestureSurface=document.querySelector('#app');
gestureSurface?.addEventListener('pointerdown',event=>{
  if(event.pointerType==='mouse'||studentDrag||!document.querySelector('#sheet').hidden||gestureControl(event.target))return;
  const view=document.querySelector('.view.active');
  pageGesture={id:event.pointerId,x:event.clientX,y:event.clientY,lastX:event.clientX,time:performance.now(),view,axis:null};
},{capture:true});
gestureSurface?.addEventListener('pointermove',event=>{
  if(!pageGesture||pageGesture.id!==event.pointerId)return;
  const dx=event.clientX-pageGesture.x,dy=event.clientY-pageGesture.y;
  if(!pageGesture.axis&&Math.hypot(dx,dy)>9)pageGesture.axis=Math.abs(dx)>Math.abs(dy)*1.15?'x':dy>0&&scrollY<=1?'pull':'y';
  if(pageGesture.axis==='pull'){
    event.preventDefault();
    const pull=Math.min(116,Math.max(0,dy)*.42),progress=Math.min(1,pull/88),app=document.querySelector('#app');
    pageGesture.pull=pull;app.classList.add('pulling-refresh');app.style.setProperty('--pull-distance',`${pull}px`);app.style.setProperty('--pull-progress',String(progress));
    const label=document.querySelector('#pullRefresh strong');if(label)label.textContent=pull>=88?'Release to refresh':'Pull to refresh';
    return;
  }
  if(pageGesture.axis!=='x')return;
  event.preventDefault();
  pageGesture.lastX=event.clientX;
  const index=mobilePageOrder.indexOf(pageGesture.view.dataset.view),atEdge=(dx>0&&index===0)||(dx<0&&index===mobilePageOrder.length-1),drag=atEdge?dx*.22:dx;
  pageGesture.view.classList.add('swiping-page');
  pageGesture.view.style.setProperty('--page-drag',`${drag}px`);
  pageGesture.view.style.setProperty('--page-fade',String(Math.max(.78,1-Math.abs(drag)/innerWidth*.18)));
},{passive:false,capture:true});
function resetPageGesture(view){view?.classList.remove('swiping-page','settling-page');view?.style.removeProperty('--page-drag');view?.style.removeProperty('--page-fade');view?.style.removeProperty('--page-enter')}
function finishPageGesture(event,cancelled=false){
  if(!pageGesture||pageGesture.id!==event.pointerId)return;
  const gesture=pageGesture;pageGesture=null;
  const dx=event.clientX-gesture.x,dy=event.clientY-gesture.y,elapsed=Math.max(1,performance.now()-gesture.time),velocity=Math.abs(dx)/elapsed;
  if(gesture.axis==='pull'){
    const app=document.querySelector('#app'),shouldRefresh=!cancelled&&(gesture.pull||0)>=88;
    app.classList.remove('pulling-refresh');app.style.removeProperty('--pull-progress');
    if(shouldRefresh){app.classList.add('refreshing-family');app.style.setProperty('--pull-distance','96px');app.style.setProperty('--pull-progress','1');refreshFamilyData()}
    else{app.classList.add('releasing-refresh');app.style.setProperty('--pull-distance','0px');setTimeout(()=>{app.classList.remove('releasing-refresh');app.style.removeProperty('--pull-distance');const label=document.querySelector('#pullRefresh strong');if(label)label.textContent='Pull to refresh'},360)}
    return;
  }
  if(gesture.axis!=='x'){resetPageGesture(gesture.view);return}
  suppressPageTap=true;setTimeout(()=>suppressPageTap=false,180);
  const index=mobilePageOrder.indexOf(gesture.view.dataset.view),direction=dx<0?1:-1,next=index+direction,complete=!cancelled&&next>=0&&next<mobilePageOrder.length&&Math.abs(dx)>Math.min(92,innerWidth*.2)&&(Math.abs(dx)>Math.abs(dy)*1.15||velocity>.55);
  if(!complete){gesture.view.classList.add('settling-page');gesture.view.style.setProperty('--page-drag','0px');gesture.view.style.setProperty('--page-fade','1');setTimeout(()=>resetPageGesture(gesture.view),210);return}
  resetPageGesture(gesture.view);
  navigate(mobilePageOrder[next],true);
  const incoming=document.querySelector('.view.active');
  incoming.classList.add('settling-page');incoming.style.setProperty('--page-enter',`${direction*24}px`);incoming.style.setProperty('--page-fade','.76');
  requestAnimationFrame(()=>requestAnimationFrame(()=>{incoming.style.setProperty('--page-enter','0px');incoming.style.setProperty('--page-fade','1')}));
  setTimeout(()=>resetPageGesture(incoming),240);
}
gestureSurface?.addEventListener('pointerup',event=>finishPageGesture(event),{capture:true});
gestureSurface?.addEventListener('pointercancel',event=>finishPageGesture(event,true),{capture:true});
document.addEventListener('click',event=>{if(suppressPageTap&&event.target.closest('#app')){event.preventDefault();event.stopImmediatePropagation()}},true);

const gestureSheet=document.querySelector('#sheet');
gestureSheet?.addEventListener('pointerdown',event=>{
  if(event.pointerType==='mouse'||gestureSheet.scrollTop>0||event.target.closest('input,select,textarea,button,a,label'))return;
  sheetGesture={id:event.pointerId,x:event.clientX,y:event.clientY,time:performance.now()};
});
gestureSheet?.addEventListener('pointermove',event=>{
  if(!sheetGesture||sheetGesture.id!==event.pointerId)return;
  const dx=event.clientX-sheetGesture.x,dy=Math.max(0,event.clientY-sheetGesture.y);
  if(dy<8||dy<Math.abs(dx)*1.1)return;
  event.preventDefault();
  gestureSheet.classList.add('swiping-down');
  gestureSheet.style.setProperty('--sheet-drag',`${Math.min(dy,220)}px`);
},{passive:false});
function finishSheetGesture(event){
  if(!sheetGesture||sheetGesture.id!==event.pointerId)return;
  const dy=event.clientY-sheetGesture.y,dx=event.clientX-sheetGesture.x,elapsed=performance.now()-sheetGesture.time;
  sheetGesture=null;
  gestureSheet.classList.remove('swiping-down');
  gestureSheet.style.removeProperty('--sheet-drag');
  if(dy>82&&dy>Math.abs(dx)*1.15&&elapsed<900)closeSheet();
}
gestureSheet?.addEventListener('pointerup',finishSheetGesture);
gestureSheet?.addEventListener('pointercancel',event=>{if(sheetGesture?.id===event.pointerId){sheetGesture=null;gestureSheet.classList.remove('swiping-down');gestureSheet.style.removeProperty('--sheet-drag')}});
